package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.StoredFile; import com.avizero.avidrive.repository.StoredFileRepository; import com.avizero.avidrive.security.AuthUser; import java.io.*; import java.nio.file.*; import java.util.*; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/files") public class PreviewController {
 private final StoredFileRepository files; private final Path cache=Path.of("storage/tmp/preview"); public PreviewController(StoredFileRepository files){this.files=files;}
 @GetMapping("/{id}/content") public ResponseEntity<?> content(@PathVariable Long id,@RequestHeader(value="Range",required=false)String range,Authentication a)throws IOException{StoredFile f=owned(id,a);if(f==null)return error(404,"Файл не найден");Path p=safeStoragePath(f.storagePath);if(p==null||!Files.isRegularFile(p))return error(404,"Файл не найден");long size=Files.size(p),start=0,end=size-1;if(range!=null&&range.startsWith("bytes=")){try{String[] v=range.substring(6).split("-");start=Long.parseLong(v[0]);if(v.length>1&&!v[1].isBlank())end=Long.parseLong(v[1]);if(start<0||start>=size||end<start)throw new Exception();end=Math.min(end,size-1);}catch(Exception e){return ResponseEntity.status(HttpStatus.REQUESTED_RANGE_NOT_SATISFIABLE).header("Content-Range","bytes */"+size).build();}}long length=end-start+1;InputStream input=Files.newInputStream(p);if(start>0){long skipped=0;while(skipped<start){long n=input.skip(start-skipped);if(n<=0){input.close();return ResponseEntity.status(HttpStatus.REQUESTED_RANGE_NOT_SATISFIABLE).header("Content-Range","bytes */"+size).build();}skipped+=n;}}Resource resource=new InputStreamResource(input);ResponseEntity.BodyBuilder builder=range==null?ResponseEntity.ok():ResponseEntity.status(HttpStatus.PARTIAL_CONTENT).header("Content-Range","bytes "+start+"-"+end+"/"+size);return builder.contentType(MediaType.parseMediaType(f.mimeType==null?MediaType.APPLICATION_OCTET_STREAM_VALUE:f.mimeType)).contentLength(length).body(resource);}
 @GetMapping("/{id}/preview") public ResponseEntity<?> preview(@PathVariable Long id,Authentication a)throws IOException{StoredFile f=owned(id,a);if(f==null)return error(404,"Файл не найден");String mime=f.mimeType==null?"":f.mimeType;if(!mime.startsWith("image/")&&!mime.equals("application/pdf"))return error(404,"Превью недоступно");Path source=safeStoragePath(f.storagePath);if(source==null||!Files.isRegularFile(source))return error(404,"Файл не найден");Files.createDirectories(cache);Path cached=cache.resolve(f.id+"-"+Math.abs(Objects.hashCode(f.updatedAt))+".preview");if(!Files.exists(cached))Files.copy(source,cached,StandardCopyOption.REPLACE_EXISTING);MediaType type=mime.equals("application/pdf")?MediaType.IMAGE_PNG:MediaType.IMAGE_JPEG;return ResponseEntity.ok().contentType(type).body(new FileSystemResource(cached));}
 @PutMapping("/{id}/content") public ResponseEntity<?> edit(@PathVariable Long id,@RequestBody EditRequest request,Authentication a)throws IOException{StoredFile f=owned(id,a);if(f==null)return error(404,"Файл не найден");if(f.updatedAt!=null&&!Objects.equals(f.updatedAt,request.expected_updated_at()))return error(409,"Файл изменён другим пользователем, обновите");Files.writeString(Path.of(f.storagePath),request.content()==null?"":request.content());f.sizeBytes=Files.size(Path.of(f.storagePath));f.updatedAt=java.time.Instant.now().toString();files.save(f);return ResponseEntity.ok(Map.of("updated_at",f.updatedAt));}
 private Path safeStoragePath(String value){if(value==null)return null;Path root=Path.of("storage/files").toAbsolutePath().normalize();Path candidate=Path.of(value).toAbsolutePath().normalize();return candidate.startsWith(root)?candidate:null;}private StoredFile owned(Long id,Authentication a){return files.findById(id).filter(x->x.ownerId.equals(((AuthUser)a.getPrincipal()).id())).orElse(null);}private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}public record EditRequest(String content,String expected_updated_at){}
}
